import sys
from collections import deque

def bfs(grid, start, visited):
    queue = deque([start])
    visited.add(start)
    component = [start]
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '#' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))
                component.append((nx, ny))
    return component

def is_connected(grid, removed):
    visited = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '#' and (i, j) not in removed and (i, j) not in visited:
                component = bfs(grid, (i, j), visited)
                if len(component) > 1:
                    return True, component
    return False, []

def main():
    import sys
    input = sys.stdin.read().split()
    n, m = int(input[0]), int(input[1])
    grid = input[2:]

    # Find any starting point in the connected component
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                start = (i, j)
                break
        if start:
            break

    # BFS to get the entire connected component
    visited = set()
    component = bfs(grid, start, visited)

    # Try removing 0, 1, and 2 squares to see if we can disconnect the component
    for k in range(3):
        for combination in combinations(component, k):
            removed = set(combination)
            if not is_connected(grid, removed)[0]:
                print(k)
                return
    print(-1)

if __name__ == "__main__":
    main()
